package io.github.jhipster.sample.config;

import java.sql.Time;
import java.sql.Types;
import java.time.OffsetDateTime;
import java.time.OffsetTime;
import org.hibernate.boot.model.TypeContributions;
import org.hibernate.boot.model.TypeContributor;
import org.hibernate.service.ServiceRegistry;
import org.hibernate.type.descriptor.WrapperOptions;
import org.hibernate.type.descriptor.java.OffsetTimeJavaType;
import org.hibernate.type.descriptor.jdbc.JdbcType;
import org.hibernate.type.descriptor.jdbc.JdbcTypeIndicators;

/**
 * Restores the Hibernate 5 storage semantics for {@link OffsetTime} attributes:
 * the value is stored in a plain {@code TIME} column as its local time
 * (the offset is dropped), honouring {@code hibernate.jdbc.time_zone}.
 * Registered through {@code META-INF/services/org.hibernate.boot.model.TypeContributor}.
 */
public class OffsetTimeTypeContributor implements TypeContributor {

    @Override
    public void contribute(TypeContributions typeContributions, ServiceRegistry serviceRegistry) {
        typeContributions.contributeJavaType(LegacyOffsetTimeJavaType.INSTANCE);
    }

    /**
     * {@link OffsetTime} Java type mapped to a {@code TIME} column like in Hibernate 5.
     */
    public static class LegacyOffsetTimeJavaType extends OffsetTimeJavaType {

        public static final LegacyOffsetTimeJavaType INSTANCE = new LegacyOffsetTimeJavaType();

        @Override
        public JdbcType getRecommendedJdbcType(JdbcTypeIndicators context) {
            return context.getTypeConfiguration().getJdbcTypeRegistry().getDescriptor(Types.TIME);
        }

        @Override
        @SuppressWarnings("unchecked")
        public <X> X unwrap(OffsetTime offsetTime, Class<X> type, WrapperOptions options) {
            if (offsetTime != null && Time.class.isAssignableFrom(type)) {
                return (X) Time.valueOf(offsetTime.toLocalTime());
            }
            return super.unwrap(offsetTime, type, options);
        }

        @Override
        public <X> OffsetTime wrap(X value, WrapperOptions options) {
            if (value instanceof Time time) {
                return OffsetTime.of(time.toLocalTime(), OffsetDateTime.now().getOffset());
            }
            return super.wrap(value, options);
        }
    }
}
